function safeJsonParse(str) {
  if (!str) return null;
  if (typeof str === "object") return str;
  if (typeof str !== "string") return null;
  var cleaned = str.trim();
  if (cleaned.indexOf("{") !== 0 && cleaned.indexOf("[") !== 0) return null;
  try {
    return JSON.parse(cleaned);
  } catch (e1) {
    try {
      var sanitized = cleaned.replace(/\r?\n/g, "\\n");
      return JSON.parse(sanitized);
    } catch (e2) {
      return null;
    }
  }
}

var aiKey = context.getVariable("request.header.x-ai-key");
var apiKey = context.getVariable("request.header.x-api-key");

if (!aiKey && apiKey) {
  context.setVariable("request.header.x-ai-key", apiKey);
}

var url = context.getVariable("proxy.url") || "";
var contentType = context.getVariable("request.header.Content-Type") || "";
var prices = context.getVariable("ai.prices");
var parsedPrices = safeJsonParse(prices);
if (!parsedPrices) {
  context.setVariable("ai.prices", JSON.stringify({
    "default": { "requestPerMillionTokens": 1, "responsePerMillionTokens": 3 }
  }));
}

var verb = context.getVariable("request.verb") || "POST";
var rawBody = "";
var requestContent = null;
if (verb !== "GET") {
  rawBody = context.getVariable("request.content") || request.content;
  try {
    requestContent = request.content.asJSON;
  } catch (e) {}
}

var reqInfo = getRequestInfo(url, rawBody, contentType);

var formModel = context.getVariable("request.formparam.model");
if (formModel && (!reqInfo.rawModelName || reqInfo.rawModelName === "" || reqInfo.modelName === "unknown")) {
  reqInfo.rawModelName = formModel;
  reqInfo.modelName = formModel.split("/").pop();
  reqInfo.protocol = "openai";
}

var aiProtocol = reqInfo.protocol;
var modelName = reqInfo.modelName;

var callStreaming = "non-streaming";
if (url.toLowerCase().includes("stream") || (requestContent && requestContent["stream"] === true)) {
  callStreaming = "streaming";
}

var modelRouting = context.getVariable("propertyset.ai.ModelRouting") || context.getVariable("propertyset.ModelRouting");
var modelRoutingConfig = context.getVariable("ai.modelRouting");
var rawModel = reqInfo.rawModelName || ((requestContent && requestContent["model"]) ? requestContent["model"] : modelName);
var routeInfo = getTargetRoute(rawModel, modelRoutingConfig);

var isRoutingEnabled = modelRouting && (modelRouting.toString().toLowerCase() === "true" || modelRouting === true);

var cleanModel = (routeInfo && routeInfo.mappedModelName) ? routeInfo.mappedModelName :
                 ((routeInfo && routeInfo.cleanModelName) ? routeInfo.cleanModelName : modelName);

if (isRoutingEnabled && routeInfo) {
  if (routeInfo.targetRoute) {
    context.setVariable("target.route", routeInfo.targetRoute);
    context.setVariable("ai.targetRoute", routeInfo.targetRoute);
  }
  if (cleanModel) {
    modelName = cleanModel;
  }
}

var effectiveProvider = (routeInfo && routeInfo.provider) ? routeInfo.provider : aiProtocol;
var targetRoute = context.getVariable("target.route") || (routeInfo ? routeInfo.targetRoute : "");
context.setVariable("ai.provider", effectiveProvider);

if (aiProtocol === "openai" && effectiveProvider !== "openai" && targetRoute !== "openai") {
  if (reqInfo.requestType === "audio-data" && effectiveProvider === "google") {
    var contentTypeHeader = context.getVariable("request.header.Content-Type") || "";
    var multipartObj = parseMultipartFormData(rawBody, contentTypeHeader);

    var formModel = context.getVariable("request.formparam.model");
    if (formModel && !multipartObj.model) multipartObj.model = formModel;
    var formPrompt = context.getVariable("request.formparam.prompt");
    if (formPrompt && !multipartObj.prompt) multipartObj.prompt = formPrompt;
    var formLang = context.getVariable("request.formparam.language");
    if (formLang && !multipartObj.language) multipartObj.language = formLang;

    requestContent = convertOpenAiPayload(multipartObj, effectiveProvider, reqInfo.requestType, routeInfo);
    context.setVariable("request.header.Content-Type", "application/json");
    request.content = JSON.stringify(requestContent);
  } else {
    requestContent = convertOpenAiPayload(requestContent, effectiveProvider, reqInfo.requestType, routeInfo);
    request.content = JSON.stringify(requestContent);
  }
} else if (requestContent && typeof requestContent === "object" && requestContent["model"]) {
  requestContent["model"] = cleanModel;
  request.content = JSON.stringify(requestContent);
}

context.setVariable("ai.protocol", aiProtocol);
context.setVariable("ai.model", modelName);
context.setVariable("ai.requestType", callStreaming);
context.setVariable("ai.apiType", aiProtocol);
context.setVariable("ai.type", reqInfo.requestType);
context.setVariable("ai.user", "unknown");

if (routeInfo && routeInfo.provider === "anthropic") {
  context.setVariable("ai.method", callStreaming === "streaming" ? "streamRawPredict" : "rawPredict");
} else if (routeInfo && routeInfo.provider === "google") {
  if (reqInfo.requestType === "embeddings") {
    context.setVariable("ai.method", "embedContent");
  } else if (callStreaming === "non-streaming") {
    context.setVariable("ai.method", "generateContent");
  } else {
    context.setVariable("ai.method", "streamGenerateContent");
  }
}

if (reqInfo.input) {
  context.setVariable("ai.requestPrompt", reqInfo.input);
} else {
  print("Could not find user input/prompt!");
}

if (context.getVariable("environment.name") === "dev") {
  print("RequestInfo: " + JSON.stringify(reqInfo));
  print("ModelRoutingEnabled: " + JSON.stringify(modelRouting));
  print("ModelRouting: " + JSON.stringify(modelRoutingConfig));
  print("TargetRoute: " + JSON.stringify(routeInfo));
}
